entries[165711] = { ["name"] = "Weihe", ["text"] = "22% von Grundmana\nSofort\nWeiht den Boden zu Füßen des Zaubernden und fügt Gegnern, die den Bereich betreten, im Verlauf von 8 Sek. Heiligschaden zu." }
entries[165712] = { ["name"] = "Aura der Hingabe", ["text"] = "Sofort\nVerleiht Gruppenmitgliedern in der Nähe 4 Min. lang Bonusrüstung." }
entries[165713] = { ["name"] = "Segen der Könige", ["text"] = "30 Meter Reichweite\nSofort\nBelegt ein befreundetes Ziel mit einem Segen, welcher 5 Min. lang seine Stärke, Beweglichkeit, Ausdauer und Intelligenz um 5% erhöht." }
entries[165714] = { ["name"] = "Heiliger Schild", ["text"] = "10% von Grundmana\nSofort\nErhöht die Blockchance 10 Sek. lang um 30% und verursacht, während der Effekt aktiv ist, mit jedem Blocken Heiligschaden. Jedes Blocken zehrt eine Aufladung auf. 3 Aufladungen." }
entries[165715] = { ["name"] = "Schild des Rächers", ["text"] = "30 Mana 30 Meter Reichweite\nWirken in 1 sek.\nSchleudert einen heiligen Schild auf den Gegner, der Heiligschaden zufügt, ihn benommen macht und dann auf weitere Gegner in der Nähe überspringt. Wirkt auf insgesamt 2 Ziele." }
entries[165716] = { ["name"] = "Garrison - Attack - Goren Spawn in, Pre-" }
entries[165717] = { ["name"] = "Arkane Explosion", ["text"] = "20 Mana\nWirken in 1 sek.\nLässt eine Druckwelle aus Magie entstehen und fügt Gegnern in der Nähe Arkanschaden zu." }
entries[165718] = { ["name"] = "Machtwort: Schild", ["text"] = "110 Mana 40 Meter Reichweite\nSofort\nUmgibt einen Verbündeten mit einem Schild, der bis zu 30 Sek. lang bestehen bleibt und Schaden absorbiert. Solange der Schild hält, werden Zauber nicht durch erlittenen Schaden unterbrochen." }
entries[165719] = { ["name"] = "Heilige Nova", ["text"] = "15 Mana\nSofort\nVerursacht eine Explosion heiligen Lichts um den Zaubernden herum und fügt allen Zielen innerhalb von 10 Metern 147 Heiligschaden zu. Zusätzlich werden alle Gruppenmitglieder innerhalb von 10 Metern um 3 Gesundheit geheilt. Dieser Effekt erzeugt keine Bedrohung." }
entries[165720] = { ["name"] = "Inneres Feuer", ["text"] = "14% von Grundmana\nSofort\nDer Zaubernde wird von einem Schub heiliger Energie erfüllt, der seine Rüstung um 10% und seine Zaubermacht um 10% erhöht." }
entries[165721] = { ["name"] = "Sühne", ["text"] = "30 Meter Reichweite\nKanalisiert (Wirken in 3 sek.)\nFeuert eine Salve heiligen Lichts, die einem Gegner 3 Sek. lang alle 1 Sek. 100 Heiligschaden zufügt." }
entries[165722] = { ["name"] = "Blutdurst", ["text"] = "Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nGreift das Ziel sofort an und verursacht 120% normalen Waffenschaden. Außredem stellen erfolgreiche Nahkampfangriffe 1% der maximalen Gesundheit wieder her. Der Effekt hält 10 Sek. lang an." }
entries[165723] = { ["name"] = "Schlachtruf", ["text"] = "Sofort\nErhöht 2 Min. lang die Nahkampfangriffskraft verbündeter Ziele in der Nähe." }
entries[165724] = { ["name"] = "Kriegsmaschinen zum Schweigen bringen: Eiserne Kriegsmaschine beschwören - Horde" }
entries[165725] = { ["name"] = "Schlitzer beschwören" }
entries[165727] = { ["name"] = "Garrison - Attack - Goren Spawn in, Pre-, Attack Guard" }
entries[165728] = { ["name"] = "Garnisonsspezialisierung erlernen: Minenwache", ["text"] = "Wirken in 3 sek.\nSchaltet die Minenwachespezialisierung für die Garnisonsmine frei." }
entries[165729] = { ["name"] = "Anhängerin: Kaz die Kreischende", ["text"] = "Sofort\nKaz die Kreischende ist für ihre Brutalität und ihre Vorliebe für brennende Dinge bekannt. Ungeachtet ihres Wahnsinns ist sie eine mächtige Schamanin." }
entries[165730] = { ["name"] = "Erlernen", ["text"] = "Wirken in 3 sek.\nGewährt Pläne, mit denen Ihr in Eurer Garnison eine Mondsturzausgrabung bauen könnt.\n\nLevel 1\nErmöglicht Spielercharakteren, draenische Steine aus Mineraladern in Draenor zu fördern. Draenische Steine können in Arbeitsaufträge für Draenormineralien umgewandelt werden.\n\nLevel 2\nBergbauanhänger können hier arbeiten, was einen einzigartigen Bonus gewährt. Außerdem enthält ein neuer Grubenschacht weitere Adern und ermöglicht bis zu 14 Arbeitsaufträge gleichzeitig.\n\nLevel 3\nEin letzter Grubenschacht ermöglicht den Zugang zu reichen Erzadern. Zusätzlich patrouillieren Garnisonswachen in der Mine und halten angriffslustige Goren fern. Ermöglicht außerdem bis zu 21 Arbeitsaufträge gleichzeitig." }
entries[165731] = { ["name"] = "Durchbohrender Ansturm", ["text"] = "100 Meter Reichweite\nSofort\nDer Zaubernde sammelt Kraft für einen mächtigen Schlag gegen das aktuelle Ziel und fügt allen, die vom Schlag erfasst werden, schweren körperlichen Schaden zu." }
entries[165732] = { ["name"] = "Durchbohrender Ansturm", ["text"] = "20 Meter Reichweite\nSofort\nDer Zaubernde sammelt Kraft für einen mächtigen Schlag gegen das aktuelle Ziel und fügt allen, die vom Schlag erfasst werden, schweren körperlichen Schaden zu." }
entries[165733] = { ["name"] = "Durchbohrender Ansturm", ["text"] = "100 Meter Reichweite\nSofort 8 sek. Abklingzeit\nDer Zaubernde sammelt Kraft für einen mächtigen Schlag gegen das aktuelle Ziel und fügt allen, die vom Schlag erfasst werden, schweren körperlichen Schaden zu." }
entries[165735] = { ["name"] = "Teufelsrüstung", ["text"] = "28% von Grundmana\nSofort\nUmgibt Euch mit Teufelsenergie, die Eure Zaubermacht um 10% erhöht. Zusätzlich regeneriert Ihr alle 5 Sek. 2% Eurer gesamten Gesundheit. Es kann immer nur eine Art Rüstungszauber gleichzeitig aktiv sein. Hält 30 Min. lang an." }
entries[165736] = { ["name"] = "Wichtel beschwören", ["text"] = "Sofort\nBeschwört einen Wichtel, der den Zaubernden bis zur Freigabe begleitet." }
entries[165737] = { ["name"] = "Erneuerung", ["text"] = "90 Mana 40 Meter Reichweite\nSofort\nHeilt einen Verbündeten 15 Sek. lang alle 3 Sek." }
entries[165738] = { ["name"] = "Heilige Nova", ["text"] = "15 Mana\nSofort\nVerursacht eine Explosion heiligen Lichts um den Zaubernden herum und fügt allen Zielen in einem Umkreis von 10 Metern 147 Heiligschaden zu. Zusätzlich werden alle Gruppenmitglieder in einem Umkreis von 10 Metern um 3 geheilt. Dieser Effekt erzeugt keine Bedrohung." }
entries[165739] = { ["name"] = "Machtwort: Seelenstärke", ["text"] = "30 Meter Reichweite\nSofort\nErfüllt das Ziel mit Lebenskraft, die seine Ausdauer 1 Stunde lang um 10% erhöht.\n\nWenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, werden alle Mitglieder den Effekt erhalten." }
entries[165740] = { ["name"] = "Heulende Böe", ["text"] = "20 Meter Reichweite\nWirken in 1.5 sek.\nWeht dem Ziel eine eisige Böe entgegen, die allen Zielen innerhalb von 10 Metern Frostschaden zufügt. Gefrorene Ziele erleiden dreifachen Schaden." }
entries[165741] = { ["name"] = "Frostnova", ["text"] = "30 Mana\nWirken in 2 sek.\nFügt Gegnern in der Nähe Frostschaden zu und macht sie bis zu 4 Sek. lang bewegungsunfähig." }
entries[165742] = { ["name"] = "Blizzard", ["text"] = "35 Mana 30 Meter Reichweite\nWirken in 2 sek.\nRuft einen Blizzard herbei, der 8 Sek. lang anhält und Gegnern im Zielgebiet alle 2 Sek. Frostschaden zufügt." }
entries[165743] = { ["name"] = "Frostrüstung", ["text"] = "Sofort 10 sek. Abklingzeit\nUmgibt den Zaubernden mit einer Frostschicht, die 30 Min. lang bestehen bleibt. Das dicke Eis erhöht die Rüstung, verringert die Bewegungsgeschwindigkeit von Nahkampfangreifern und erhöht die Zeit zwischen ihren Angriffen." }
entries[165744] = { ["name"] = "Göttlicher Sturm", ["text"] = "20% von Grundmana Nahkampfreichweite\nSofort\nEin sofortiger Waffenangriff, der bis zu 4 Gegnern innerhalb von 8 Metern Heiligschaden zufügt." }
entries[165745] = { ["name"] = "Siegel der Wahrheit", ["text"] = "14% von Grundmana\nSofort\nErfüllt den Paladin mit heiliger Macht, durch den Angriffe auf Einzelziele den Effekt 'Tadel' auslösen, der im Verlauf von 5 Min. [(0.01 * Zaubermacht + 0.0193 * Angriffskraft) * 5 */ 100] zusätzlichen Heiligschaden verursacht. 'Tadel' ist bis zu 0-mal stapelbar. Sobald 0 Stapel erreicht werden, verursacht jeder Angriff des Paladins zusätzlich 0% Waffenschaden als Heiligschaden. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein. Hält 5 Min. lang an.\n\nDie Entfesselung der Energie dieses Siegels fügt einem Gegner (1 + 0.223 * Zaubermacht + 0.142 * Angriffskraft) Heiligschaden zu, dieser Schaden wird für jeden Stapel von 'Tadel' auf dem Ziel um 10% erhöht." }
entries[165746] = { ["name"] = "Aura der Vergeltung", ["text"] = "Sofort\nFügt jeder Kreatur, die den Zaubernden trifft, Heiligschaden zu." }
entries[165747] = { ["name"] = "Segen der Macht", ["text"] = "30 Meter Reichweite\nSofort\nBelegt ein verbündetes Ziel mit einem Segen, der 5 Min. lang seine Angriffskraft um 10%, seine Distanzangriffskraft um 10% erhöht und alle 5 Sek. 1% Mana regeneriert." }
entries[165748] = { ["name"] = "Demoralisierender Ruf", ["text"] = "Sofort\nVerringert 20 Sek. lang die Nahkampfangriffskraft von Gegnern in der Nähe." }
entries[165749] = { ["name"] = "Donnerknall", ["text"] = "Sofort\nFügt nahen Gegnern Naturschaden zu, erhöht die Zeit zwischen ihren Angriffen und verringert ihre Bewegungsgeschwindigkeit. Hält 6 Sek. lang an." }
entries[165750] = { ["name"] = "Befehlsruf", ["text"] = "Sofort\nErhöht die maximale Gesundheit aller Gruppenmitglieder im Umkreis von 20 Metern um 10%. Hält 2 Min. lang an." }
entries[165751] = { ["name"] = "Schockwelle", ["text"] = "Wirken in 2 sek. 20 sek. Abklingzeit\nSchickt dem Krieger eine Energiewelle voraus, verursacht Schaden und betäubt alle Einheiten innerhalb eines kegelförmigen Bereichs von 10 Metern für 4 Sek." }
entries[165752] = { ["name"] = "Verjüngung", ["text"] = "90 Mana 40 Meter Reichweite\nSofort\nHeilt einen Verbündeten 12 Sek. lang alle 3 Sek." }
entries[165753] = { ["name"] = "Nachwachsen", ["text"] = "280 Mana 40 Meter Reichweite\nWirken in 2 sek.\nHeilt einen Verbündeten um einen festgelegten Wert und heilt dann 21 Sek. lang alle 3 Sek. weiteren Schaden." }
entries[165754] = { ["name"] = "Mal der Wildnis", ["text"] = "30 Meter Reichweite\nSofort\nErhöht Stärke, Beweglichkeit und Intelligenz eines verbündeten Ziels 1 Stunde lang um 5%. Wenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, werden alle Mitglieder den Effekt erhalten." }
entries[165755] = { ["name"] = "Dolchfächer", ["text"] = "40 Energie\nSofort\nBenötigt Nahkampfwaffe\nWirft sofort Dolche nach allen Gegnern in der Nähe und verursacht 100% Waffenschaden." }
entries[165756] = { ["name"] = "Schmiedesturm", ["text"] = "Kanalisiert (Wirken in 4 sek.)\nEntfesselt einen Glutsturm, der nahen Gegnern Feuerschaden zufügt." }
entries[165757] = { ["name"] = "Feuerregen", ["text"] = "35 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 9 sek.)\nLässt einen Feuerregen niedergehen, der alle Gegner im Zielgebiet verbrennt und ihnen 9 Sek. lang alle 3 Sek. Feuerschaden zufügt." }
entries[165758] = { ["name"] = "Feuerbrandfalle", ["text"] = "Sofort 15 sek. Abklingzeit\nEine Feuerfalle platzieren, die dem ersten sich nähernden Gegner im Verlauf von 15 Sek. Feuerschaden zufügt. Die Falle besteht 1 Min. lang." }
entries[165759] = { ["name"] = "Schmiedesturm", ["text"] = "40 Meter Reichweite\nSofort\nEntfesselt einen Glutsturm, der nahen Gegnern Feuerschaden zufügt." }
entries[165760] = { ["name"] = "Herzstoß", ["text"] = "1 Rune / -10 Runenmacht Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nSchlägt das Ziel und seinen nächsten Verbündeten sofort. Fügt dem Primärziel 110% Waffenschaden und dem Sekundärziel 55% Waffenschaden zu." }
entries[165761] = { ["name"] = "Tod und Verfall", ["text"] = "30 Meter Reichweite\nSofort\nFügt allen Zielen im Zielbereich 10 Sek. lang alle 1 Sek. Schattenschaden zu." }
entries[165762] = { ["name"] = "Horn des Winters", ["text"] = "Sofort\nDer Todesritter bläst das Horn des Winters und erhält 10 Runenmacht. Stärke und Beweglichkeit werden um 8 erhöht. Hält 2 Min. lang an." }
entries[165763] = { ["name"] = "Blutwurm", ["text"] = "30 Meter Reichweite\nSofort\nErschafft einen Blutwurm, der nahe Ziele angreift. Hält 8 Sek. lang an." }
entries[165764] = { ["name"] = "Psychischer Schrei", ["text"] = "210 Mana\nSofort\nStößt einen psychischen Schrei aus, der bis zu 5 Gegner in der Nähe für 4 Sek. in die Flucht schlägt." }
entries[165765] = { ["name"] = "Leiche auferwecken" }
entries[165766] = { ["name"] = "Dispersion", ["text"] = "Sofort\nLöst Euch zu reiner Schattenenergie auf und verringert sämtlichen erlittenen Schaden um 75%. Ihr könnt nicht angreifen oder Zauber wirken, regeneriert jedoch 6 Sek. lang pro Sekunde 90% Mana. 'Dispersion' kann gewirkt werden, während Betäubungs-, Furcht- oder Stilleeffekte auf Euch wirken. Bei Anwendung werden alle wirkenden Verlangsamungs- und bewegungseinschränkenden Effekte entfernt und Ihr werdet für die Dauer des Effekts von 'Dispersion' gegen sie immun." }
entries[165767] = { ["name"] = "Schattengestalt", ["text"] = "40% von Grundmana\nSofort\nNimmt Schattengestalt an, erhöht verursachten Schattenschaden um 20% und verringert erlittenen Nahkampfschaden um 20%. Die Schattengestalt hält an, bis die Aktion abgebrochen wird." }
entries[165768] = { ["name"] = "Schattenschritt", ["text"] = "20 Energie 40 Meter Reichweite\nSofort 30 sek. Abklingzeit\nVersucht, in die Schatten zu tauchen, um hinter dem Gegner zu erscheinen." }
entries[165769] = { ["name"] = "Frostfalle", ["text"] = "Sofort\nPlatziert eine Frostfalle, die 30 Sek. lang um sich herum eine Eisfläche bildet, sobald sich ihr der erste Gegner nähert. Die Bewegungsgeschwindigkeit aller Gegner in einem Umkreis von 10 Metern wird um 50% verringert, solange sie sich im Effektbereich befinden. Die Falle bleibt 30 Sek. lang bestehen. Es kann immer nur jeweils eine Falle aktiv sein." }
entries[165770] = { ["name"] = "Prankenhieb", ["text"] = "Nahkampfreichweite\nSofort\nSchlägt Gegner in der Nähe und verursacht körperlichen Schaden." }
entries[165771] = { ["name"] = "Dornen", ["text"] = "30 Meter Reichweite\nSofort\nAus dem verbündeten Ziel sprießen Dornen, die jedem Angreifer Naturschaden zufügen. Hält 10 Min. lang an." }
entries[165772] = { ["name"] = "Welle der Heilung", ["text"] = "145 Mana 40 Meter Reichweite\nWirken in 3 sek.\nRuft Naturmagie an, um einen Verbündeten zu heilen." }
entries[165773] = { ["name"] = "Erdschild", ["text"] = "40 Meter Reichweite\nSofort\nSchützt das Ziel mit einem Erdschild. Nahkampfangriffe heilen das geschützte Ziel, dieser Effekt tritt aber nur einmal alle paar Sekunden auf. 10 Aufladungen. Hält 10 Min. lang an.\n(3.5s Abklingzeit)" }
entries[165774] = { ["name"] = "Totem der Erdbindung", ["text"] = "30 Mana\nSofort\nTools: Erdtotem\nBeschwört ein Totem der Erdbindung, das 45 Sek. lang bestehen bleibt und in regelmäßigen Abständen die Bewegungsgeschwindigkeit von Gegnern in der Nähe auf 50% der normalen Geschwindigkeit verringert." }
entries[165775] = { ["name"] = "Antimagisches Feld", ["text"] = "1 Rune / -10 Runenmacht\nSofort\nPlatziert ein großes, ortsgebundenes antimagisches Feld, das den erlittenen Zauberschaden aller darin befindlichen Gruppen- oder Schlachtzugsmitglieder um 49% verringert. Das antimagische Feld hält 6 Sek. lang an oder bis es (0 + 2 * Angriffskraft) Zauberschaden absorbiert hat." }
entries[165776] = { ["name"] = "Giftdurchwobenes Netz", ["text"] = "7 Meter Reichweite\nKanalisiert (Wirken in 4 sek.)\nUmhüllt einen Gegner mit giftigen Netzen, die diesem alle 5.2 Sek. Naturschaden zufügen und ihn 4 Sek. lang bewegungsunfähig machen." }
entries[165777] = { ["name"] = "Giftdurchwobenes Netz", ["text"] = "10 Meter Reichweite\nSofort\nUmhüllt einen Gegner mit giftigen Netzen, die diesem alle 5.2 Sek. Naturschaden zufügen und ihn 4 Sek. lang bewegungsunfähig machen." }
entries[165778] = { ["name"] = "Kampfrausch", ["text"] = "10 Mana\nSofort\nErhöht 30 Sek. lang das Angriffstempo eines Verbündeten um 30%." }
entries[165779] = { ["name"] = "Infizierter Biss", ["text"] = "Nahkampfreichweite\nSofort\nBeißt einen Gegner und verursacht eine juckende Wunde, die ihm 6 Sek. lang alle 2 Sek. Naturschaden zufügt.\nBei Erlöschen wird ein 'Spinnlingausbruch' ausgelöst." }
entries[165780] = { ["name"] = "Spinnlingausbruch", ["text"] = "40 Meter Reichweite\nSofort\nLässt Spinnlinge aus einem Gegner herausbrechen, was ihm Naturschaden zufügt." }
