entries[165803] = { ["name"] = "Telaartalbuk", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Telaartalbuk oder gibt ihn wieder frei. Der Talbuk kann im Kampf geritten werden ." }
entries[165804] = { ["name"] = "Feuerstab des Kriegsmeisters", ["text"] = "Wirken in 3 sek.\nTools: Schreibzeug des Virtuosen\nOhne Beruf:\nReagenzien:\nEinfaches Holz , Kriegsbemalung (100)\nOptionale Reagenzien:\n[] (#49) , Waffenkristall (#242)\nVerkäufer:\nMaru'sa\nZone:\nKriegsspeer\nKosten:\n1\n\nFeuerstab des Kriegsmeisters\nWird beim Anlegen gebunden\nEinzigartig anlegbar: Warlords - hergestellt (3)Distanz Zauberstab\n1 - 3 Feuerschaden Geschwindigkeit 2.00\n(1.0 Schaden pro Sekunde)\n+13 Intelligenz\n+3 Ausdauer\nHaltbarkeit 90 / 90\n35" }
