entries[165813] = { ["name"] = "Verbrenner", ["text"] = "45 Meter Reichweite\nWirken in 2 sek.\nDer Abfackler äschert alles seinem Weg ein und verursacht 20 Sek. lang alle 1 Sek. 2 Feuerschaden." }
